/**
 * Hand-labelled evaluation set for the promise/document matcher (hemsida-4np.4).
 * `pairs.json` is generated by `tools/prepare-eval-set.ts` with empty labels; the
 * user fills `label` (and optionally `note`) with `tools/label-eval-set.ts`.
 */
import { z } from 'zod';

export const evalLabelSchema = z.enum(['match', 'partial', 'contradicts', 'no_match']);
export type EvalLabel = z.infer<typeof evalLabelSchema>;

/** How far along the process the document is; a separate axis from the relevance label. */
export const evalStageSchema = z.enum(['definitive', 'preparatory', 'background']);
export type EvalStage = z.infer<typeof evalStageSchema>;

export const evalPairSchema = z.strictObject({
  /** Stable key: `<promise_id>::<document_id>`. */
  id: z.string().min(1),
  promise_id: z.string().min(1),
  /** Promise title and description (Swedish, as on the site). */
  promise_title: z.string(),
  promise_text: z.string(),
  promise_quote: z.string(),
  document_id: z.string().min(1),
  document_title: z.string(),
  /** dir, sou, ds, prop or bet. */
  document_type: z.string(),
  /** Short context shown to the labeller: reference, date, committee and which queries found it. */
  snippet: z.string(),
  url: z.string(),
  /** Candidate-search score (number of distinct queries that returned the document). */
  search_score: z.number().int().positive(),
  /** Null until labelled. */
  label: evalLabelSchema.nullable(),
  /** Hand-set document stage; absent until the user labels it. */
  stage: evalStageSchema.optional(),
  note: z.string().optional(),
});
export type EvalPair = z.infer<typeof evalPairSchema>;

export const evalFileSchema = z.strictObject({
  term: z.string(),
  seed: z.number().int(),
  pairs: z.array(evalPairSchema),
});
export type EvalFile = z.infer<typeof evalFileSchema>;

/** One model's blind full-text judgement of a pair. Never the ground truth; the hand label is. */
export const modelJudgementSchema = z.strictObject({
  label: evalLabelSchema,
  /** How far along the document is (decision, inquiry/proposal, or mere mention); not asked of every model. */
  stage: evalStageSchema.optional(),
  confidence: z.enum(['high', 'medium', 'low']),
  reason: z.string().min(1),
});
export type ModelJudgement = z.infer<typeof modelJudgementSchema>;

/** Baseline from models labelling pairs blind (no hand label visible), keyed by pair id, then model name. */
export const modelLabelsFileSchema = z.strictObject({
  term: z.string(),
  /** Where the judgements come from, so the baseline can be compared with or reproduced later. */
  meta: z.strictObject({
    generated: z.string().min(1),
    /** What "blind" means and what each model was given. */
    method: z.string().min(1),
    /** Per model name: which model ran and how it was prompted (prompts can differ between models). */
    models: z.record(z.string(), z.string().min(1)),
  }),
  labels: z.record(z.string(), z.record(z.string(), modelJudgementSchema)),
});
export type ModelLabelsFile = z.infer<typeof modelLabelsFileSchema>;
